import{_t as e,it as t,n,rt as r}from"./chunks/framework.BVGGWBQY.js";var i=JSON.parse(`{"title":"Tool reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788732279000}`),a={name:`reference/tools.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="tool-reference" tabindex="-1">Tool reference <a class="header-anchor" href="#tool-reference" aria-label="Permalink to “Tool reference”">​</a></h1><p>All 17 tools: 10 read, 7 write. With <code>CARDDAV_READ_ONLY=true</code> the write tools are not registered at all — they do not appear in <code>tools/list</code>.</p><p>All 17 are registered unless you say otherwise. <code>CARDDAV_ALLOW_TOOLS</code> and <code>CARDDAV_DENY_TOOLS</code> narrow the list to the ones you want, and <code>CARDDAV_ALLOW_TOOLS=essential</code> selects the 6 marked <strong>essential</strong> below — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>👤 marks a tool that <strong>asks a person</strong> before it acts, through MCP elicitation — a dialog the model cannot answer on its behalf. Where the client cannot show one, it falls back to a two-call <code>confirm_token</code> bound to the exact target and expiring after five minutes, and says which of the two it was. <code>ELICITATION=false</code> takes that fallback deliberately; it never removes the guard. See <a href="/guide/approval">Asking a person</a>.</p><p>Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>. They are a hint a client may ignore; the dialog is enforced here and cannot be, which is why the two lists are not the same one.</p><p>Every tool also declares an <code>outputSchema</code> and answers in both channels at once — the same object as <code>structuredContent</code>, and as JSON in a text block. Every answer built from address book content additionally carries <code>untrusted: true</code> and <code>source: &quot;carddav&quot;</code> as <strong>fields</strong>, so a client can check rather than notice. Two tools deliberately do not: <code>get_server_info</code> and <code>list_changes</code> return this server&#39;s own words — protocol tokens, ids and counts, with no card content in them at all. A marker on everything would be a marker on nothing.</p><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><h3 id="list-address-books" tabindex="-1"><code>list_address_books</code> <a class="header-anchor" href="#list-address-books" aria-label="Permalink to “list_address_books”">​</a></h3><p><strong>List the address books</strong> — read-only, <strong>essential</strong></p><p>Every address book this server may use, with the id to pass to the other tools. Always asks the server rather than answering from a cache — being current is this tool’s whole job.</p><p>Takes no parameters.</p><h3 id="get-server-info" tabindex="-1"><code>get_server_info</code> <a class="header-anchor" href="#get-server-info" aria-label="Permalink to “get_server_info”">​</a></h3><p><strong>What the connected CardDAV server can do</strong> — read-only</p><p>Reports the DAV compliance tokens, which vCard versions each address book accepts, and whether the optional features this server relies on actually work here. The first thing to run when something behaves differently than expected — CardDAV implementations differ more than the specification suggests.</p><p>Takes no parameters.</p><h3 id="list-contacts" tabindex="-1"><code>list_contacts</code> <a class="header-anchor" href="#list-contacts" aria-label="Permalink to “list_contacts”">​</a></h3><p><strong>List contacts</strong> — read-only, <strong>essential</strong></p><p>Contacts in one or more address books, as short summaries: name, organisation, addresses and phone numbers, and whether a photo is present. Only the summary properties are fetched, so this stays cheap on a large address book — get_contact returns the whole card.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_books</code></td><td>string[]</td><td>no</td><td>Which address books to look in. Leave it out for every address book this server may see.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr><tr><td><code>include_groups</code></td><td>boolean</td><td>no</td><td>Include group cards in the listing. Off by default: a group is a vCard like any other, and mixing them into a contact list is usually not what was meant. list_groups reads them properly.</td></tr></tbody></table><h3 id="get-contact" tabindex="-1"><code>get_contact</code> <a class="header-anchor" href="#get-contact" aria-label="Permalink to “get_contact”">​</a></h3><p><strong>Read one contact in full</strong> — read-only, <strong>essential</strong></p><p>The complete card behind an id: every address, every phone number, the note, the birthday, and the names of any properties this server does not model. The free text comes back inside a fence marking it as somebody else’s writing.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr></tbody></table><h3 id="search-contacts" tabindex="-1"><code>search_contacts</code> <a class="header-anchor" href="#search-contacts" aria-label="Permalink to “search_contacts”">​</a></h3><p><strong>Find contacts</strong> — read-only, <strong>essential</strong></p><p>Finds contacts whose name, organisation, email address, phone number or note contains a term. One request per address book — CardDAV combines the fields with OR, unlike CalDAV — and the result is checked again here, because some servers filter only partially.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>yes</td><td>The term to look for. Matched case-insensitively.</td></tr><tr><td><code>fields</code></td><td><code>&quot;FN&quot;</code> | <code>&quot;N&quot;</code> | <code>&quot;NICKNAME&quot;</code> | <code>&quot;EMAIL&quot;</code> | <code>&quot;TEL&quot;</code> | <code>&quot;ORG&quot;</code> | <code>&quot;TITLE&quot;</code> | <code>&quot;NOTE&quot;</code> | <code>&quot;CATEGORIES&quot;</code> | <code>&quot;UID&quot;</code>[]</td><td>no</td><td>Which vCard properties to match against. Defaults to FN, NICKNAME, EMAIL, TEL and ORG — the fields somebody searches by.</td></tr><tr><td><code>address_books</code></td><td>string[]</td><td>no</td><td>Which address books to look in. Leave it out for every address book this server may see.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr></tbody></table><h3 id="get-contact-photo" tabindex="-1"><code>get_contact_photo</code> <a class="header-anchor" href="#get-contact-photo" aria-label="Permalink to “get_contact_photo”">​</a></h3><p><strong>Fetch a contact’s photo</strong> — read-only</p><p>Returns the photo stored on a card as an image. Only a photo embedded in the card itself — one stored as a link is reported by get_contact and never fetched, because that address was chosen by whoever wrote the card. The media type is decided from the bytes, never from what the card claims: JPEG, PNG, GIF and WebP are handed over, and bytes that are none of those are refused with a sentence rather than delivered under a generic label.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr></tbody></table><h3 id="export-contacts" tabindex="-1"><code>export_contacts</code> <a class="header-anchor" href="#export-contacts" aria-label="Permalink to “export_contacts”">​</a></h3><p><strong>Export contacts as vCard text</strong> — read-only</p><p>The raw vCard text of one or more contacts, exactly as stored. The only way to see a property this server does not model, and the only way to take a backup of an address book from here.</p><p>This is the one tool whose two channels differ on purpose. <code>structuredContent</code> carries the cards byte for byte — that is the backup. The text block is a rendering of the same cards for reading, inside the nonce fence with every line datamarked: invisible characters are removed and markdown image markers are broken there, so a <code>NOTE</code> carrying <code>![…](https://…)</code> cannot make a client fetch a URL when it renders the answer. The first line of the text block says so. Injection shapes found in the exported cards are reported as a warning above the fence.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>ids</code></td><td>string[]</td><td>no</td><td>Specific contacts. Leave out to export a whole book.</td></tr><tr><td><code>address_book</code></td><td>string</td><td>no</td><td>Export every card in this address book.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr></tbody></table><h3 id="list-changes" tabindex="-1"><code>list_changes</code> <a class="header-anchor" href="#list-changes" aria-label="Permalink to “list_changes”">​</a></h3><p><strong>What changed in an address book</strong> — read-only</p><p>Cards created, changed or deleted since a sync token, using RFC 6578. Call it once without a token to get the current token, then again later with it. Not every server implements this — get_server_info reports whether this one does.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_book</code></td><td>string</td><td>yes</td><td>An address book id from list_address_books — its collection path. A full URL or the final path segment work too.</td></tr><tr><td><code>sync_token</code></td><td>string</td><td>no</td><td>The token from a previous call. Left out, this returns the current token and every card, which is the initial sync.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr></tbody></table><h3 id="list-groups" tabindex="-1"><code>list_groups</code> <a class="header-anchor" href="#list-groups" aria-label="Permalink to “list_groups”">​</a></h3><p><strong>List contact groups</strong> — read-only</p><p>Groups in one or more address books, with how many members each has. The members themselves are not resolved here — that is one extra request per book, and get_group is where a caller has said they want the names.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_books</code></td><td>string[]</td><td>no</td><td>Which address books to look in. Leave it out for every address book this server may see.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr></tbody></table><h3 id="get-group" tabindex="-1"><code>get_group</code> <a class="header-anchor" href="#get-group" aria-label="Permalink to “get_group”">​</a></h3><p><strong>Read one group, with its members</strong> — read-only</p><p>A group card and the contacts in it, resolved to names and ids where the members live in the same address book. A member this server cannot resolve is still reported, as the reference the card holds.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr></tbody></table><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><h3 id="create-contact" tabindex="-1"><code>create_contact</code> <a class="header-anchor" href="#create-contact" aria-label="Permalink to “create_contact”">​</a></h3><p><strong>Add a contact</strong> — write, <strong>essential</strong></p><p>Adds a card to an address book. The UID and the file name are generated here. The vCard version follows what the address book accepts — 3.0 unless it says otherwise, because that is what phones and desktop clients read completely.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_book</code></td><td>string</td><td>yes</td><td>An address book id from list_address_books — its collection path. A full URL or the final path segment work too.</td></tr><tr><td><code>formatted_name</code></td><td>unknown</td><td>no</td><td>FN, the display name. Derived from the name parts when left out on create. Null removes it, which no valid card may be without.</td></tr><tr><td><code>given_name</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>family_name</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>additional_names</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>name_prefix</code></td><td>unknown</td><td>no</td><td>Dr, Prof.</td></tr><tr><td><code>name_suffix</code></td><td>unknown</td><td>no</td><td>Jr, PhD.</td></tr><tr><td><code>nickname</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>organization</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>department</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>title</code></td><td>unknown</td><td>no</td><td>Job title.</td></tr><tr><td><code>role</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>emails</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>phones</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>urls</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>instant_messaging</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>addresses</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>birthday</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>anniversary</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>note</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>raw_vcard</code></td><td>string</td><td>no</td><td>A complete vCard to store as-is, instead of the fields above. For properties this server does not model.</td></tr></tbody></table><h3 id="update-contact-👤" tabindex="-1"><code>update_contact</code> 👤 <a class="header-anchor" href="#update-contact-👤" aria-label="Permalink to “update_contact 👤”">​</a></h3><p><strong>Change a contact</strong> — write, destructive, <strong>essential</strong></p><p>Changes the fields named and leaves everything else exactly as it was — including properties this server does not model. Guarded by the card’s ETag, so a change made elsewhere in the meantime is refused rather than overwritten. A CardDAV server keeps no version history, so a person is asked first.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>formatted_name</code></td><td>unknown</td><td>no</td><td>FN, the display name. Derived from the name parts when left out on create. Null removes it, which no valid card may be without.</td></tr><tr><td><code>given_name</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>family_name</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>additional_names</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>name_prefix</code></td><td>unknown</td><td>no</td><td>Dr, Prof.</td></tr><tr><td><code>name_suffix</code></td><td>unknown</td><td>no</td><td>Jr, PhD.</td></tr><tr><td><code>nickname</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>organization</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>department</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>title</code></td><td>unknown</td><td>no</td><td>Job title.</td></tr><tr><td><code>role</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>emails</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>phones</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>urls</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>instant_messaging</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>addresses</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>birthday</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>anniversary</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>note</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>raw_vcard</code></td><td>string</td><td>no</td><td>Replace the whole card with this one. Unlike the named fields, this does not merge — anything not in it is gone.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table><h3 id="delete-contact-👤" tabindex="-1"><code>delete_contact</code> 👤 <a class="header-anchor" href="#delete-contact-👤" aria-label="Permalink to “delete_contact 👤”">​</a></h3><p><strong>Delete a contact</strong> — write, destructive</p><p>Removes a card. Cannot be undone — a CardDAV server has no trash and no version history. Guarded by the card’s ETag, so a card changed since it was read is refused rather than deleted blind. A group card is refused, before anybody is asked: <code>delete_group</code> is the tool for that, and the two stay separable in <code>CARDDAV_DENY_TOOLS</code> only because this one cannot reach a group.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table><h3 id="move-contact-👤" tabindex="-1"><code>move_contact</code> 👤 <a class="header-anchor" href="#move-contact-👤" aria-label="Permalink to “move_contact 👤”">​</a></h3><p><strong>Move a contact to another address book</strong> — write, destructive</p><p>Copies a card into another address book and removes it from the first. The id changes, because an id names a card in a collection. There is no transaction behind this: the copy is verified before the original is removed.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>destination</code></td><td>string</td><td>yes</td><td>The address book to move the card into.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table><h3 id="create-group" tabindex="-1"><code>create_group</code> <a class="header-anchor" href="#create-group" aria-label="Permalink to “create_group”">​</a></h3><p><strong>Create a contact group</strong> — write</p><p>Creates a group card and puts the named contacts in it. The convention follows whatever groups the address book already uses, because a group written the other way is invisible in the client the person is actually looking at.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_book</code></td><td>string</td><td>yes</td><td>An address book id from list_address_books — its collection path. A full URL or the final path segment work too.</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>The group’s display name.</td></tr><tr><td><code>note</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>members</code></td><td>string[]</td><td>no</td><td>Contact ids to put in the group.</td></tr></tbody></table><h3 id="update-group-👤" tabindex="-1"><code>update_group</code> 👤 <a class="header-anchor" href="#update-group-👤" aria-label="Permalink to “update_group 👤”">​</a></h3><p><strong>Rename a group or change who is in it</strong> — write, destructive</p><p>Changes a group’s name or note, and adds or removes members. Removing a member removes the grouping only — the contact itself is untouched. A CardDAV server keeps no version history, so a person is asked first.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>note</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>add_members</code></td><td>string[]</td><td>no</td><td></td></tr><tr><td><code>remove_members</code></td><td>string[]</td><td>no</td><td></td></tr><tr><td><code>set_members</code></td><td>string[]</td><td>no</td><td>Replace the membership outright with exactly these contacts. Cannot be combined with add_members or remove_members.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table><h3 id="delete-group-👤" tabindex="-1"><code>delete_group</code> 👤 <a class="header-anchor" href="#delete-group-👤" aria-label="Permalink to “delete_group 👤”">​</a></h3><p><strong>Delete a contact group</strong> — write, destructive</p><p>Removes a group card. The contacts that were in it are not touched — only the grouping goes. Cannot be undone.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table>`,77)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};